async function wb(action,data={}){const r=await fetch('/api/workbench/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...data})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
const wbScenario={title:'Demo project review',situation:'A fictional project sponsor questions your release plan.',goal:'Explain evidence and propose a reversible pilot.',rubric:['Acknowledge uncertainty','Offer a rollback plan'],character:'Project sponsor',traits:['Cautious','Direct'],background:'I worry about service disruption. I value tested evidence. I have seen a failed launch. I will consider a small pilot.',condition:'rollback plan',resistance:'How will you reverse the change if the pilot fails?',agreement:'A reversible pilot addresses my concern. Let us review its test evidence.'};
const beforeWorkbench=render;render=function(){if(location.hash==='#agent-workbench'){document.getElementById('app').innerHTML=integratedShell('agent-workbench',heading('Agent workbench','Pre-launch · Demo · Local retrieval and text scenarios')+`<section class="card prose"><p id="wb-status" role="status"></p><a href="#agent-runtime">Approved action runner</a></section><section class="card prose"><h2>Private retrieval memory</h2><p>Hashed word vectors; not semantic model embeddings. Only your course/account records are searched.</p><form data-wb="remember"><label>Remember a note<textarea name="body" required maxlength="4000"></textarea></label><button class="button">Save memory</button></form><form data-wb="search"><label>Search<input name="query" required></label><button class="button">Search</button></form><form data-wb="forget"><label>Memory ID to delete<input name="id" required></label><button class="button secondary">Delete my memory</button></form></section><section class="card prose"><h2>Hosted planning</h2><button data-wb-button="planner_status" class="button">Check configuration</button><form data-wb="plan"><label>Synthetic planning goal<textarea name="goal" required maxlength="2000"></textarea></label><p>Instructor only. Sends this goal to Anthropic; no memory or scenario records are sent. May incur provider charges.</p><button class="button">Request model plan</button></form><button data-wb-button="plans" class="button secondary">View my saved plans</button><p>Up to three model decisions per run; twenty runs per account per day. Write proposals require review. These limits are not a monetary budget.</p><h2>Local MCP connection</h2><button data-wb-button="mcp_tools" class="button">Discover tools</button><button data-wb-button="mcp_call" class="button">Read course standard</button></section><section class="card prose"><h2>Scenario authoring</h2><p>Instructor only. Hidden persona fields are never returned by the learner listing. Text simulation uses an exact phrase condition, not an AI judgment.</p><form id="wb-scenario"><label>Structured scenario JSON<textarea name="config" rows="12">${esc(JSON.stringify(wbScenario,null,2))}</textarea></label><button class="button">Create scenario</button></form><button data-wb-button="scenarios" class="button secondary">List learner-visible scenarios</button><form data-wb="scenario_start"><label>Scenario ID<input name="id" required></label><button class="button">Start</button></form><form data-wb="scenario_turn"><label>Session ID<input name="session" required></label><label>Your response<textarea name="answer" required></textarea></label><button class="button">Respond</button></form></section><section class="card prose"><h2>Result</h2><pre id="wb-result" style="white-space:pre-wrap" aria-live="polite"></pre></section>`,model.role);bind();}else beforeWorkbench();const n=document.querySelector('aside nav')||document.querySelector('aside');if(n&&!n.querySelector('[href="#agent-workbench"]'))n.insertAdjacentHTML('beforeend','<a href="#agent-workbench">Agent workbench</a>');};
async function wbShow(action,data){try{const d=await wb(action,data);document.getElementById('wb-result').textContent=JSON.stringify(d,null,2);document.getElementById('wb-status').textContent='Operation completed.';}catch(e){document.getElementById('wb-result').textContent='';document.getElementById('wb-status').textContent=e.message;}}
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.wb&&!['wb-connect','wb-scenario'].includes(f.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(f.id==='wb-connect'){governedToken=d.token;f.reset();wbShow('scenarios',{});}else if(f.id==='wb-scenario'){try{wbShow('scenario_create',{config:JSON.parse(d.config)});}catch(err){document.getElementById('wb-status').textContent=err.message;}}else wbShow(f.dataset.wb,{...d,synthetic:f.dataset.wb==='plan'});});document.addEventListener('click',e=>{const b=e.target.closest('[data-wb-button]');if(b)wbShow(b.dataset.wbButton,{});});render();
